const b = $input.first().json.body || {};
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const items = Array.isArray(b.items) ? b.items : [];
const color = {kritiek: '#b3261e', fout: '#b3261e', waarschuwing: '#a86a00', info: '#2f5d50'}[b.level] || '#2f5d50';
const rows = items.map(i => `<tr><td style="padding:8px;border-bottom:1px solid #eee;vertical-align:top"><b>${esc(i.title)}</b><br><span style="color:#555">${esc(i.message)}</span>${i.link ? `<br><a href="${esc(i.link)}">Openen</a>` : ''}</td></tr>`).join('');
const html = `<div style="font-family:Arial,sans-serif;max-width:640px"><div style="background:${color};color:#fff;padding:12px 16px;border-radius:8px 8px 0 0"><b>AI Product Studio</b> · ${esc(b.level || 'info')}</div><div style="border:1px solid #eee;border-top:0;padding:16px;border-radius:0 0 8px 8px"><h2 style="margin:0 0 8px;font-size:18px">${esc(b.subject)}</h2>${b.intro ? `<p>${esc(b.intro)}</p>` : ''}<table style="width:100%;border-collapse:collapse">${rows}</table>${b.html_extra || ''}<p style="color:#888;font-size:12px;margin-top:16px">Automatische melding · ${new Date().toLocaleString('nl-NL', {timeZone: 'Europe/Amsterdam'})}</p></div></div>`;
const prefix = {kritiek: '🚨', fout: '❌', waarschuwing: '⚠️', info: 'ℹ️'}[b.level] || 'ℹ️';
return [{json: {subject: `${prefix} AI Product Studio: ${b.subject || 'melding'}`, html}}];
